MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  ExceptionInfo
    *exception;

  FILE
    *file;

  IndexPacket
    *indexes;

  MagickBooleanType
    status;

  MagickPixelPacket
    *colormap;

  register ssize_t
    i;

  size_t
    count;

  if (image == (Image *) NULL)
    return(MagickFalse);
  exception=GetExceptionInfo();
  file=fopen(image_info->filename,"wb");
  if (file == (FILE *) NULL)
    {
      ThrowFileException(&image->exception,CanNotOpenFileError,
        image_info->filename,image_info->filename);
      return(MagickFalse);
    }
  status=TransformImageColorspace(image,sRGBColorspace);
  if (status == MagickFalse)
    {
      fclose(file);
      return(MagickFalse);
    }
  count=image->colors;
  if (count > 65536)
    {
      fclose(file);
      return(MagickFalse);
    }
  colormap=AcquireImageColormap(image,exception);
  if (colormap == (MagickPixelPacket *) NULL)
    {
      fclose(file);
      return(MagickFalse);
    }
  for (i=0; i < (ssize_t) count; i++)
  {
    fwrite(&colormap[i].red,sizeof(unsigned short),1,file);
    fwrite(&colormap[i].green,sizeof(unsigned short),1,file);
    fwrite(&colormap[i].blue,sizeof(unsigned short),1,file);
  }
  indexes=GetImageIndexes(image);
  if (indexes == (IndexPacket *) NULL)
    {
      fclose(file);
      return(MagickFalse);
    }
  for (i=0; i < (ssize_t) image->rows; i++)
    for (ssize_t x=0; x < (ssize_t) image->columns; x++)
    {
      fputc((unsigned char) indexes[i*image->columns + x], file);
    }
  fclose(file);
  return(MagickTrue);
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  Image
    *copy_image;

  ExceptionInfo
    *exception;

  register const Quantum
    *p;

  register ssize_t
    x;

  size_t
    colormap_size,
    count;

  MagickBooleanType
    status;

  register ssize_t
    i;

  MagickPixelPacket
    *colormap;

  FILE
    *file;

  /*
   * Unregister the MAP image format.
   */
  UnregisterImageFormat("MAP");

  exception = &image->exception;

  if ((image->columns == 0) || (image->rows == 0))
    return(MagickFalse);

  copy_image = CloneImage(image, image->columns, image->rows, MagickTrue, exception);
  if (copy_image == (Image *) NULL)
    return(MagickFalse);

  status = MagickTrue;

  (void) TransformImageColorspace(copy_image, sRGBColorspace);

  if ((file = fopen(image->filename, "wb")) == (FILE *) NULL)
  {
    InheritException(exception, &copy_image->exception);
    copy_image = DestroyImage(copy_image);
    return(MagickFalse);
  }

  colormap_size = copy_image->colors;
  colormap = (MagickPixelPacket *) AcquireQuantumMemory((size_t) colormap_size, sizeof(*colormap));
  if (colormap == (MagickPixelPacket *) NULL)
  {
    fclose(file);
    copy_image = DestroyImage(copy_image);
    (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError, "UnableToAcquireColormap", "Memory");
    return(MagickFalse);
  }

  count = 0;
  GetImageColormap(copy_image, colormap);

  if (colormap_size <= 256)
  {
    for (i = 0; i < (ssize_t) colormap_size; i++)
    {
      unsigned char red = ScaleQuantumToChar(colormap[i].red);
      unsigned char green = ScaleQuantumToChar(colormap[i].green);
      unsigned char blue = ScaleQuantumToChar(colormap[i].blue);
      if (fwrite(&red, sizeof(unsigned char), 1, file) != 1 ||
          fwrite(&green, sizeof(unsigned char), 1, file) != 1 ||
          fwrite(&blue, sizeof(unsigned char), 1, file) != 1)
      {
        status = MagickFalse;
        break;
      }
    }
  }
  else
  {
    for (i = 0; i < (ssize_t) colormap_size; i++)
    {
      unsigned short red = ScaleQuantumToShort(colormap[i].red);
      unsigned short green = ScaleQuantumToShort(colormap[i].green);
      unsigned short blue = ScaleQuantumToShort(colormap[i].blue);
      if (fwrite(&red, sizeof(unsigned short), 1, file) != 1 ||
          fwrite(&green, sizeof(unsigned short), 1, file) != 1 ||
          fwrite(&blue, sizeof(unsigned short), 1, file) != 1)
      {
        status = MagickFalse;
        break;
      }
    }
  }

  if (status != MagickTrue)
  {
    fclose(file);
    RelinquishMagickMemory(colormap);
    copy_image = DestroyImage(copy_image);
    return(MagickFalse);
  }

  p = GetImagePixels(copy_image, 0, 0, copy_image->columns, 1);
  for (y = 0; y < (ssize_t) copy_image->rows; y++)
  {
    for (x = 0; x < (ssize_t) copy_image->columns; x++)
    {
      unsigned char index = (unsigned char) GetPixelIndex(p);
      if (fwrite(&index, sizeof(unsigned char), 1, file) != 1)
      {
        status = MagickFalse;
        break;
      }
      p += copy_image->pixels;
    }

    if (status != MagickTrue)
      break;

    p = SyncCacheViewRow(copy_image, y);
  }

  if (fwrite == MagickFalse)
  {
    fclose(file);
    RelinquishMagickMemory(colormap);
    copy_image = DestroyImage(copy_image);
    return(MagickFalse);
  }

  fclose(file);
  RelinquishMagickMemory(colormap);
  copy_image = DestroyImage(copy_image);
  return(MagickTrue);
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  ExceptionInfo *exception;
  unsigned char *map_colormap;
  unsigned char *map_pixels;
  int
    map_file;
  size_t
    number_colors;

  if ((image == (Image *) NULL) || (image->signature != MagickSignature))
    return(MagickFalse);

  if ((image_info == (ImageInfo *) NULL) || (image_info->signature != MagickSignature))
    return(MagickFalse);

  exception = &image->exception;
  if (image->colors > 256)
    number_colors = 256;
  else
    number_colors = image->colors;

  if ((map_file = fopen(image->filename, "wb")) == (FILE *) NULL)
  {
    InheritException(exception, &image->exception);
    return(MagickFalse);
  }

  if (image->colorspace != sRGBColorspace)
    (void) TransformImageColorspace(image, sRGBColorspace, exception);

  map_colormap = (unsigned char *) AcquireMemory(number_colors * 3 * sizeof(*map_colormap));
  if (map_colormap == (unsigned char *) NULL)
  {
    fclose(map_file);
    ThrowException(exception, ResourceLimitError, MemoryAllocationFailed,
                   "colormap");
    return(MagickFalse);
  }

  {
    register int
      i;

    register PixelPacket
      *p;

    register unsigned char
      *q;

    q = map_colormap;
    p = image->pixels;
    for (i = 0; i < (int) number_colors; i++)
    {
      *q++ = ScaleQuantumToChar(p->red);
      *q++ = ScaleQuantumToChar(p->green);
      *q++ = ScaleQuantumToChar(p->blue);
      p++;
    }
  }

  (void) fwrite(map_colormap, 3, (size_t) number_colors, map_file);
  if (image->colors > 256)
  {
    unsigned int
      index;

    map_pixels = (unsigned char *) AcquireMemory(image->columns * image->rows * sizeof(*map_pixels));
    if (map_pixels == (unsigned char *) NULL)
    {
      fclose(map_file);
      RelinquishMemory(map_colormap);
      ThrowException(exception, ResourceLimitError, MemoryAllocationFailed,
                     "pixels");
      return(MagickFalse);
    }

    {
      register int
        x,
        y;

      register unsigned int
        *p;

      register unsigned char
        *q;

      p = (unsigned int *) image->indexes;
      q = map_pixels;
      for (y = 0; y < (int) image->rows; y++)
        for (x = 0; x < (int) image->columns; x++)
          *q++ = (unsigned char) *p++;
    }

    (void) fwrite(map_pixels, 1, image->columns * image->rows, map_file);
    RelinquishMemory(map_pixels);
  }

  fclose(map_file);
  RelinquishMemory(map_colormap);
  return(MagickTrue);
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  MagickBooleanType status;
  FILE *file;

  if ((file = fopen(image_info->filename, "wb")) == (FILE *) NULL)
  {
    ThrowFileException(&image->exception, FileOpenError, UnableToCreate,
      image_info->filename);
    return (MagickFalse);
  }

  image->depth = 8;
  (void) TransformImageColorspace(image, sRGBColorspace);

  if (image->colors > 256)
  {
    (void) ThrowMagickException(&image->exception, MagickFunction,
      WriteImageError, MAPImageError, "`%s' (only 256 colors allowed)",
      image_info->filename);
    return (MagickFalse);
  }

  {
    size_t length;
    register PixelIndex *p;
    register ssize_t x;
    ssize_t y;
    PixelIndex *indexes;

    length = 256U * sizeof(*indexes);
    indexes = (PixelIndex *) AcquireQuantumMemory((size_t) image->rows,
      sizeof(*indexes));
    if (indexes == (PixelIndex *) NULL)
    {
      (void) fclose(file);
      return (MagickFalse);
    }

    p = indexes;
    for (y = 0; y < (ssize_t) image->rows; y++)
    {
      register const Quantum *magick_restrict q;
      register const Quantum *magick_restrict p;

      q = GetVirtualCacheViewRow(image,y);
      p = indexes + (y*image->columns);
      for (x = 0; x < (ssize_t) image->columns; x++)
      {
        *p++ = ClampToByte(q[x]);
      }
    }

    for (y = 0; y < (ssize_t) image->rows; y++)
    {
      register const Quantum *magick_restrict q;
      register const Quantum *magick_restrict p;

      q = GetVirtualCacheRow(image,y);
      p = indexes + (y*image->columns);
      for (x = 0; x < (ssize_t) image->columns; x++)
      {
        *p++ = ClampToByte(q[x]);
      }
    }

    if (fwrite(indexes, sizeof(*indexes), length, file) != length)
    {
      (void) fclose(file);
      indexes = (PixelIndex *) RelinquishMagickMemory(indexes);
      return (MagickFalse);
    }

    indexes = (PixelIndex *) RelinquishMagickMemory(indexes);
  }

  status = (MagickBooleanType) fclose(file);
  if (status == MagickFalse)
    return (MagickFalse);

  return (MagickTrue);
}
